const listConnections = `-- name: ListConnections :many
SELECT id, realm_id, slug, type, config, created_at FROM authn_connections WHERE realm_id = ? ORDER BY slug
`

func (q *Queries) ListConnections(ctx context.Context, realmID string) ([]AuthnConnection, error) {
	rows, err := q.db.QueryContext(ctx, listConnections, realmID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []AuthnConnection
	for rows.Next() {
		var i AuthnConnection
		if err := rows.Scan(
			&i.ID,
			&i.RealmID,
			&i.Slug,
			&i.Type,
			&i.Config,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

